
'use strict';
const baseRender=render,basePage=page;
render=function(){baseRender();if(state.page==='exposicao')exposureView()};
page=function(id){basePage(id);if(['teoria','exposicao'].includes(id)){$('#page-label').textContent=id==='teoria'?'Teoria e governança':'Exposição e comparação';$('.filters').style.opacity='.48';$$('.filters select').forEach(e=>e.disabled=true);$('#scope').textContent=id==='teoria'?'Proposta teórica · evidências e extensões documentadas':'Universo PNCT vinculado · filtros próprios abaixo';$('#export').style.display='none'}};
const mechanisms={governanca:'Hipótese: obrigações claras, recursos e coordenação favorecem informação e resposta. Medir contratos, responsabilidades e execução; o regime cadastral não é uma medida suficiente de qualidade.',observacao:'Hipótese: cobertura operacional e integração aumentam concordância e completude. É necessário histórico de equipamentos e confronto de fontes; mais registros não provam maior risco.',indicador:'O indicador combina ocorrência e observação. A exposição PNCT melhora o denominador, mas não identifica eventos não registrados.',resposta:'Hipótese: alertas com responsável, recursos e acompanhamento levam a respostas mais rápidas. Exige documentos datados; persistência não comprova ausência de intervenção.'};
$$('[data-mechanism]').forEach(b=>b.onclick=()=>$('#mechanism-detail').textContent=mechanisms[b.dataset.mechanism]);$('#mechanism-detail').textContent=mechanisms.governanca;
[...new Set(EXPOSICAO.rows.map(r=>r[1]))].sort().forEach(u=>$('#expo-uf').add(new Option(u,u)));
$$('.expo-filters select').forEach(e=>e.onchange=exposureView);
function exposureView(){let yr=$('#expo-year').value,uf=$('#expo-uf').value,out=$('#expo-outcome').value,ix=out==='mortos'?10:9,rows=EXPOSICAO.rows.filter(r=>(yr==='all'||r[0]===+yr)&&(uf==='all'||r[1]===uf)),groups=[...new Set(rows.map(r=>r[8]))].map(a=>{let g=rows.filter(r=>r[8]===a);return {name:a,n:g.reduce((s,r)=>s+r[ix],0),e:g.reduce((s,r)=>s+r[7],0)}});let n=groups.reduce((s,g)=>s+g.n,0),e=groups.reduce((s,g)=>s+g.e,0);$('#expo-kpis').innerHTML=[['Segmentos-ano',N(rows.length)],['Desfecho registrado',N(n)],['Veículos-km estimados',N(e/1e9,2)+' bi'],['Taxa por 100 milhões',e?N(n/e*1e8,2):'—']].map(([a,b])=>`<div class="kpi"><span>${a}</span><strong>${b}</strong></div>`).join('');$('#expo-reading').textContent='As taxas consideram somente registros vinculados aos segmentos elegíveis. Os filtros alteram a descrição; os modelos abaixo permanecem nacionais e fixos.';
for(let [id,rate]of[['expo-counts',false],['expo-rates',true]])plot(id,{grid:{left:75,right:25,bottom:85,top:20},tooltip:{trigger:'axis'},xAxis:{type:'category',data:groups.map(g=>g.name.replace(' no cadastro PNCT','')),axisLabel:{width:140,overflow:'break',interval:0}},yAxis:{type:'value'},series:[{type:'bar',data:groups.map(g=>rate?g.n/g.e*1e8:g.n),itemStyle:{color:C.teal},label:{show:true,position:'top',formatter:p=>N(p.value,rate?2:0)}}]});
$('#expo-rate-label').textContent=(out==='mortos'?'Mortes':'Sinistros')+' por 100 milhões de veículos-quilômetro';$('#expo-counts-reading').textContent='Uma contagem maior pode refletir mais circulação. Compare também a taxa ao lado.';$('#expo-rates-reading').textContent='Diferenças brutas podem refletir infraestrutura, composição do tráfego e registro. Não ordenam a qualidade da governança.';
let ts=['n','mortos'].map(k=>({...EXPOSICAO.models[k].terms.find(t=>t.term==='concessao'),name:k==='n'?'Sinistros':'Mortes'}));plot('nb-forest',{grid:{left:90,right:45,top:20,bottom:40},tooltip:{formatter:p=>{let t=ts[p.dataIndex];return `${t.name}: ${N(t.irr,3)} [${N(t.low,3)}; ${N(t.high,3)}]`}},xAxis:{type:'value',min:.8,max:2},yAxis:{type:'category',data:ts.map(t=>t.name)},series:[{type:'scatter',symbolSize:12,data:ts.map((t,i)=>[t.irr,i]),markLine:{symbol:'none',data:[{xAxis:1}]},itemStyle:{color:C.teal}},{type:'custom',renderItem:(p,a)=>{let t=ts[p.dataIndex],l=a.coord([t.low,p.dataIndex]),h=a.coord([t.high,p.dataIndex]);return {type:'line',shape:{x1:l[0],y1:l[1],x2:h[0],y2:h[1]},style:{stroke:C.teal,lineWidth:3}}},data:ts.map((t,i)=>[t.irr,i])}]});
$('#nb-reading').textContent='O ajuste altera a comparação bruta. A associação para mortes perde evidência estatística ao excluir segmentos não simuláveis; não sustenta uma conclusão causal sobre concessões.';$('#nb-diagnostics').innerHTML=Object.entries(EXPOSICAO.models).map(([k,m])=>`<p><b>${k==='n'?'Sinistros':'Mortes'}:</b> ${N(m.meta.n)} segmentos-ano; ${m.meta.clusters} grupos UF–BR; dispersão Poisson ${N(m.meta.poisson_pearson,2)}. NB2 α=${N(m.meta.alpha,3)}.</p>`).join('');$('#nb-sensitivity').innerHTML='<thead><tr><th>Sensibilidade · mortes</th><th>IRR concessão [IC 95%]</th></tr></thead><tbody>'+Object.entries(EXPOSICAO.sensitivity).map(([k,m])=>{let t=m.terms.find(t=>t.term==='concessao');return `<tr><td>${k==='sem_2025'?'Excluir 2025':'Excluir não simuláveis'}</td><td>${N(t.irr,3)} [${N(t.low,3)}; ${N(t.high,3)}]</td></tr>`}).join('')+'</tbody>';$('#expo-coverage').innerHTML='<thead><tr><th>Ano</th><th>Segmentos</th><th>PRF vinculados / total</th><th>Cobertura</th></tr></thead><tbody>'+EXPOSICAO.coverage.map(c=>`<tr><td>${c.ano}</td><td>${N(c.segmentos_elegiveis)}</td><td>${N(c.ocorrencias_vinculadas)} / ${N(c.ocorrencias_prf)}</td><td>${N(100*c.ocorrencias_vinculadas/c.ocorrencias_prf,1)}%</td></tr>`).join('')+'</tbody>';
}
page(location.hash.slice(1)||'visao');

const baseTerritory=territory;
territory=function(){baseTerritory();let layer=$('#map-layer').value;if(layer==='events'){$('#map-interpretation').textContent='Pontos representam intervalos de 10 km com registros, não coordenadas individuais nem taxas de risco.';return}let u=$('#uf').value,b=$('#br').value,uf=u==='all'?null:REGISTROS.cats.uf[+u],roads=RODOVIAS.filter(r=>(!uf||r.uf===uf)&&(b==='all'||r.br===+b));let counts=new Map;for(let r of state.filtered){let id=r[15];if(id==null)continue;let a=counts.get(id)||{n:0,mortos:0,graves:0};a.n++;a.mortos+=r[11];a.graves+=r[12];counts.set(id,a)}let metric=$('#map-metric').value,data=roads.flatMap(r=>r.lines.map(line=>({name:'BR-'+String(r.br).padStart(3,'0')+' / '+r.uf+' · km '+r.km.join('–'),coords:line,value:(counts.get(r.id)||{})[metric]||0,admin:r.admin,lineStyle:{color:layer==='admin'?(r.admin.includes('Concess')?'#b77a16':'#655652'):layer==='network'?'#766b65':((counts.get(r.id)||{})[metric]>0?'#a33b32':'#c9bfb5'),width:layer==='network'?1:1.6,opacity:.8}})));plot('map',{tooltip:{formatter:p=>esc(p.name)+'<br>'+esc(p.data.admin||'')+'<br>'+N(p.value||0)+' registros do desfecho no recorte'},geo:{map:'brasil',roam:true,layoutCenter:['49%','48%'],layoutSize:'100%',itemStyle:{areaColor:'#eee8e0',borderColor:'#fff'},emphasis:{label:{show:true}}},series:[{type:'lines',coordinateSystem:'geo',polyline:true,data,silent:false,progressive:0}]});$('#map-subtitle').textContent='Traçado oficial SNV 202604A · '+N(roads.length)+' segmentos';$('#map-interpretation').textContent=layer==='admin'?'Âmbar: concessão no cadastro de 2026; cinza: demais administrações. É uma referência cadastral atual, sem reconstrução da governança histórica.':layer==='network'?'Traçado dos eixos principais federais pavimentados, duplicados e implantados. Simplificado apenas para visualização.':'Vermelho: segmento com desfecho registrado no recorte; cinza: sem correspondência de desfecho. Não é uma estimativa de risco ou de persistência ajustada.';};
$('#map-layer').onchange=territory;$('#map-metric').onchange=territory;

const labPage=page;page=function(id){labPage(id);if(id==='laboratorio'){$('#page-label').textContent='Laboratório de evidências';$('.filters').style.opacity='.48';$$('.filters select').forEach(e=>e.disabled=true);$('#scope').textContent='Reprodução, fontes e protocolo de pesquisa';$('#export').style.display='none'}};page(location.hash.slice(1)||'visao');

const baseMethods=methods;
methods=function(){baseMethods();$('#sources').innerHTML=FONTES.map(f=>{let name=f.file,prf=name.startsWith('prf'),pnct=name.startsWith('pnct'),snv=name.startsWith('snv'),ibge=name.includes('geojson'),desc=prf?'Ocorrências PRF por ano; ZIP → CSV com separador ponto e vírgula e codificação legada. Uma linha por ocorrência. Auditoria, conversão de campos, localização e gravidade derivada.':pnct?'Plano Nacional de Contagem de Tráfego/DNIT: planilha VMD ou nota técnica anual. Extração OOXML somente leitura; soma dos sentidos C+D e intervalos estimados.':snv?'Sistema Nacional de Viação/DNIT, versão 202604A. ZIP → SHP/DBF. Correspondência UF–BR–km; geometrias para visualização e diagnóstico retrospectivo.':ibge?'Instituto Brasileiro de Geografia e Estatística: malha simplificada das UFs em GeoJSON. Base cartográfica, não denominador populacional.':'Agência Nacional de Transportes Terrestres: cadastro ou catálogo oficial. CSVs auditados estruturalmente; datas e campos preservados. Não convertem cadastro atual em governança histórica.';return `<details><summary>${esc(name)} · ${N(f.bytes||0)} bytes</summary><p>${desc}</p><p><a href="${esc(f.url)}" target="_blank" rel="noopener">Acessar arquivo na origem oficial ↗</a> · <a href="https://github.com/alexandrerodrigues2311/observatorio-seguranca-rodoviaria/releases/tag/dados-2026-10-17" target="_blank">Versão preservada ↗</a></p><p>Data de coleta/verificação do manifesto: ${esc(f.retrieved_at||'não registrada')}. O provedor pode atualizar o endereço original; confira o hash da versão utilizada.</p><code style="overflow-wrap:anywhere">SHA-256: ${esc(f.sha256||'não disponível')}</code></details>`}).join('')};

const basePlot=plot;
plot=function(id,option){let ss=option.series||[],cat=(option.xAxis?.type==='category'?option.xAxis:option.yAxis?.type==='category'?option.yAxis:null);if(ss.length===1&&ss[0].type==='bar'&&cat?.data?.length===1){let v=ss[0].data[0];v=typeof v==='object'?v.value:v;return basePlot(id,{graphic:[{type:'text',left:'center',top:'30%',style:{text:N(v,Number.isInteger(v)?0:2),font:'600 40px Segoe UI',fill:C.teal}},{type:'text',left:'center',top:'53%',style:{text:String(cat.data[0])+' · categoria única no recorte',font:'13px Segoe UI',fill:C.ink}}]})}let ch=basePlot(id,option);if(id==='trend'){ch.off('click');ch.on('click',e=>{$('#year').value=String(e.name);filter()})}if(id==='severity-chart'){ch.off('click');ch.on('click',e=>{let n=REGISTROS.cats.gravidade.indexOf(e.name);if(n>=0){$('#severity').value=String(n);filter()}})}return ch};page(location.hash.slice(1)||'visao');
